package cn.binbin.crm;
import jakarta.validation.*;import jakarta.validation.constraints.*;import java.time.*;import java.math.BigDecimal;import java.util.*;import java.util.function.Function;import org.springframework.stereotype.Service;import static cn.binbin.crm.TradeService.*;import static cn.binbin.crm.P3Base.map;
/** Bounded templates create drafts through domain services; failed commits roll back the entire batch. */
@Service
public class MigrationService {
 public record Preview(@NotBlank String entityType,@NotBlank @Size(max=200) String fileName,@NotBlank @Size(max=710000) String csvBase64){}
 public record Commit(@Min(0) long expectedVersion){}
 public record Draft(@NotNull @Size(max=20) Map<String,String> values){}
 static final LinkedHashMap<String,List<String>> COLUMNS=new LinkedHashMap<>();static {COLUMNS.put("LEAD",List.of("联系人","公司名称","行业","来源","地区","电话","邮箱","备注"));COLUMNS.put("PRODUCT",List.of("产品编码","产品名称","类别","单位","售价（元）","成本（元）","税率（%）","产品分类","说明"));COLUMNS.put("ORDER",List.of("批准报价编号","订单名称","预计交付日期","备注"));COLUMNS.put("INVOICE",List.of("合同编号","开票标题","购方名称","税号","金额（元）","备注"));COLUMNS.put("EXPENSE",List.of("资金账户","收款方","支出类别","金额（元）","付款日期","付款流水号","备注"));COLUMNS.put("TARGET",List.of("目标对象","月份","周期月数","目标金额（元）"));COLUMNS.put("WEEKLY",List.of("周起始日","工作进展","本周成果","风险事项","下周计划"));}
 private final P7Records r;private final P3Base b;private final P7Permissions p;private final Validator validator;
 public MigrationService(P7Records r,P7Permissions p,Validator validator){this.r=r;this.b=r.b;this.p=p;this.validator=validator;}
 private <T>T manage(AuthService.Session s,boolean write,Function<AuthService.Actor,T> fn){return b.tx.execute(st->{if(write)b.db.queryForObject("SELECT id FROM sys_tenant WHERE id=:tenant FOR UPDATE",map("tenant",s.tenantId()),UUID.class);var a=b.auth.actor(s);p.admin(a);if(write)p.feature(a,"migration");return fn.apply(a);});}
 public Object draftTemplates(AuthService.Session s){return b.tx.execute(st->{var a=b.auth.actor(s);if(a.supportGrantId()!=null)throw ApiError.forbidden("支持授权不含快捷新增");return map("items",COLUMNS.entrySet().stream().filter(e->r.allowed(a,e.getKey(),true)).map(e->map("id",e.getKey(),"name",P7Records.NAMES.get(e.getKey()),"columns",e.getValue())).toList());});}
 public Object templates(AuthService.Session s){return manage(s,false,a->map("items",COLUMNS.entrySet().stream().filter(e->r.allowed(a,e.getKey(),true)).map(e->map("id",e.getKey(),"name",P7Records.NAMES.get(e.getKey()),"columns",e.getValue())).toList(),"maxRows",200,"plan",SaasService.view(p.plan(a)),"atomicCommit",true));}
 public byte[] template(AuthService.Session s,String type){return manage(s,false,a->{if(!COLUMNS.containsKey(type)||!r.allowed(a,type,true))throw ApiError.forbidden("没有此模板对应写入权限");return CsvSupport.write(COLUMNS.get(type),List.of());});}
 private String value(Map<String,String> values,String key){return text(values.get(key));}
 private long amount(String input){try{BigDecimal n=new BigDecimal(input);if(n.scale()>2||n.signum()<0)throw new IllegalArgumentException();long v=n.movePointRight(2).longValueExact();if(v>100000000000L)throw new IllegalArgumentException();return v;}catch(Exception e){throw ApiError.bad("金额需为非负数，最多两位小数且不超过10亿元");}}
 private UUID reference(AuthService.Actor a,String type,String supplied){try{UUID id=UUID.fromString(supplied);r.get(a,type,id,false);return id;}catch(IllegalArgumentException ignored){}String field=type.equals("QUOTE")?"quote_number":"contract_number";var rows=b.db.queryForList("SELECT id FROM "+P7Records.TABLES.get(type)+" WHERE tenant_id=:tenant AND "+field+"=:value",map("tenant",a.tenant().id(),"value",supplied),UUID.class);if(rows.size()!=1)throw ApiError.bad("业务编号不存在或不唯一");r.get(a,type,rows.getFirst(),false);return rows.getFirst();}
 Object parse(AuthService.Actor a,String type,Map<String,String> v){if(!COLUMNS.containsKey(type)||!COLUMNS.get(type).containsAll(v.keySet()))throw ApiError.bad("模板类型或列名无效");Object input=switch(type){
 case "LEAD"->new BusinessService.LeadCreate(value(v,"联系人"),value(v,"公司名称"),value(v,"行业"),value(v,"来源"),value(v,"地区"),"",value(v,"电话"),value(v,"邮箱"),value(v,"备注"),a.tenant().memberId());
 case "PRODUCT"->{String kind=switch(value(v,"类别")){case "产品","PRODUCT"->"PRODUCT";case "服务","SERVICE"->"SERVICE";default->throw ApiError.bad("类别填写产品或服务");};int tax;try{tax=new BigDecimal(value(v,"税率（%）").isBlank()?"13":value(v,"税率（%）")).movePointRight(2).intValueExact();}catch(Exception e){throw ApiError.bad("税率最多两位小数");}yield new CommerceService.ProductInput(value(v,"产品编码"),value(v,"产品名称"),kind,value(v,"单位"),amount(value(v,"售价（元）")),amount(value(v,"成本（元）").isBlank()?"0":value(v,"成本（元）")),tax,value(v,"产品分类"),value(v,"说明"),"ACTIVE",0);}
 case "ORDER"->{UUID quote=reference(a,"QUOTE",value(v,"批准报价编号"));var source=r.get(a,"QUOTE",quote,false);if(!"APPROVED".equals(source.get("status")))throw ApiError.bad("来源报价须已批准");yield new SalesOrderService.Create(quote,number(source,"version"),value(v,"订单名称"),value(v,"预计交付日期").isBlank()?null:LocalDate.parse(value(v,"预计交付日期")),value(v,"备注"));}
 case "INVOICE"->new FinanceWorkspaceService.InvoiceInput(reference(a,"CONTRACT",value(v,"合同编号")),value(v,"开票标题"),value(v,"购方名称"),value(v,"税号"),amount(value(v,"金额（元）")),value(v,"备注"));
 case "EXPENSE"->{String account=value(v,"资金账户");var options=b.db.queryForList("SELECT id FROM crm_fund_account WHERE tenant_id=:tenant AND active AND(name=:name OR id::text=:name)",map("tenant",a.tenant().id(),"name",account),UUID.class);if(options.size()!=1)throw ApiError.bad("资金账户不存在或名称不唯一");yield new FinanceWorkspaceService.ExpenseInput(options.getFirst(),value(v,"收款方"),value(v,"支出类别"),amount(value(v,"金额（元）")),LocalDate.parse(value(v,"付款日期")),value(v,"付款流水号"),value(v,"备注"));}
 case "TARGET"->{String target=value(v,"目标对象");UUID member=null,department=null;if(target.startsWith("部门：")){var ids=b.db.queryForList("SELECT id FROM org_department WHERE tenant_id=:tenant AND name=:name AND active",map("tenant",a.tenant().id(),"name",target.substring(3)),UUID.class);if(ids.size()!=1)throw ApiError.bad("部门名称不存在或不唯一");department=ids.getFirst();}else{var ids=b.db.queryForList("SELECT m.id FROM sys_tenant_member m JOIN iam_user u ON u.id=m.user_id WHERE m.tenant_id=:tenant AND u.username=:name AND m.status='ACTIVE' AND u.status='ACTIVE'",map("tenant",a.tenant().id(),"name",target),UUID.class);if(ids.size()!=1)throw ApiError.bad("目标成员账号无效");member=ids.getFirst();}String month=value(v,"月份");LocalDate start=LocalDate.parse(month.length()==7?month+"-01":month);yield new PerformanceService.TargetInput(member,department,start,Integer.parseInt(value(v,"周期月数").isBlank()?"1":value(v,"周期月数")),amount(value(v,"目标金额（元）")),0);}
 case "WEEKLY"->new PerformanceService.WeeklyInput(LocalDate.parse(value(v,"周起始日")),value(v,"工作进展"),value(v,"本周成果"),value(v,"风险事项"),value(v,"下周计划"),0);
 default->throw ApiError.bad("模板类型无效");};var errors=validator.validate(input);if(!errors.isEmpty())throw ApiError.bad(errors.iterator().next().getPropertyPath()+"："+errors.iterator().next().getMessage());return input;}
 Object create(AuthService.Actor a,String type,Object input,String key,UUID trace){if(!r.allowed(a,type,true))throw ApiError.forbidden("当前角色没有此对象写入权限");return switch(type){case "LEAD"->r.business.createLead(a.session(),(BusinessService.LeadCreate)input,key,trace);case "PRODUCT"->r.commerce.createProduct(a.session(),(CommerceService.ProductInput)input,key,trace);case "ORDER"->r.orders.create(a.session(),(SalesOrderService.Create)input,key,trace);case "INVOICE"->r.fw.invoiceCreate(a.session(),(FinanceWorkspaceService.InvoiceInput)input,key,trace);case "EXPENSE"->r.fw.expenseCreate(a.session(),(FinanceWorkspaceService.ExpenseInput)input,key,trace);case "TARGET"->r.perf.saveTarget(a.session(),null,(PerformanceService.TargetInput)input,key,trace);case "WEEKLY"->r.perf.weeklySave(a.session(),null,(PerformanceService.WeeklyInput)input,key,trace);default->throw ApiError.bad("对象不支持草稿导入");};}
 public Object draft(AuthService.Session s,String type,Draft i,String key,UUID trace){return r.scope(s,type,true,a->{p.feature(a,"workspace");var input=parse(a,type,i.values());return create(a,type,input,key,trace);});}
 private Map<String,Object> batch(AuthService.Actor a,UUID id){var row=b.one("SELECT * FROM crm_migration_batch WHERE tenant_id=:tenant AND id=:id AND member_id=:member",map("tenant",a.tenant().id(),"id",id,"member",a.tenant().memberId()));if(!r.allowed(a,(String)row.get("entityType"),true))throw ApiError.forbidden("业务权限已变化，请联系管理员");return row;}
 private Map<String,Object> view(Map<String,Object> raw){var out=new LinkedHashMap<>(raw);for(String field:List.of("rowsData","results"))if(out.get(field)!=null)try{out.put(field,b.data.json.readValue(String.valueOf(out.get(field)),Object.class));}catch(Exception e){throw new IllegalStateException(e);}return out;}
 public Object preview(AuthService.Session s,Preview i,String key,UUID trace){return manage(s,true,a->{if(!COLUMNS.containsKey(i.entityType())||!r.allowed(a,i.entityType(),true))throw ApiError.forbidden("没有此模板对应写入权限");if(!i.fileName().toLowerCase(Locale.ROOT).endsWith(".csv"))throw ApiError.bad("请选择CSV文件");byte[] bytes;try{bytes=Base64.getDecoder().decode(i.csvBase64());}catch(Exception e){throw ApiError.bad("文件编码无效");}var rows=CsvSupport.parse(bytes,200);if(rows.size()<2||!rows.getFirst().values().equals(COLUMNS.get(i.entityType())))throw ApiError.bad("请下载并使用当前模板，保持表头和顺序不变");var output=new ArrayList<Object>();for(var row:rows.subList(1,rows.size())){Map<String,String> values=new LinkedHashMap<>();var issues=new ArrayList<String>();if(row.values().size()!=COLUMNS.get(i.entityType()).size())issues.add("列数不匹配");else for(int n=0;n<row.values().size();n++)values.put(COLUMNS.get(i.entityType()).get(n),row.values().get(n));if(issues.isEmpty())try{parse(a,i.entityType(),values);}catch(Exception e){issues.add(e instanceof ApiError?e.getMessage():"日期、数字或资料格式无效");}output.add(map("number",row.number(),"values",values,"errors",issues));}UUID id=b.once(a,"migration.preview",key,map("type",i.entityType(),"name",i.fileName(),"hash",Crypto.hash(i.csvBase64())),()->{UUID n=UUID.randomUUID();b.db.update("INSERT INTO crm_migration_batch(id,tenant_id,member_id,entity_type,file_name,rows_data) VALUES(:id,:tenant,:member,:type,:file,cast(:rows AS jsonb))",map("id",n,"tenant",a.tenant().id(),"member",a.tenant().memberId(),"type",i.entityType(),"file",i.fileName(),"rows",b.json(output)));b.audit(a,"MIGRATION_PREVIEWED","MIGRATION",n,0,trace);return n;});return view(batch(a,id));});}
 public Object get(AuthService.Session s,UUID id){return manage(s,false,a->view(batch(a,id)));}
 public Object batches(AuthService.Session s){return manage(s,false,a->map("items",b.rows("SELECT id,entity_type,file_name,status,version,created_at,committed_at FROM crm_migration_batch WHERE tenant_id=:tenant AND member_id=:member ORDER BY created_at DESC,id LIMIT 100",map("tenant",a.tenant().id(),"member",a.tenant().memberId()))));}
 @SuppressWarnings("unchecked") public Object commit(AuthService.Session s,UUID id,Commit i,String key,UUID trace){return manage(s,true,a->{UUID result=b.once(a,"migration.commit",key,new TradeService.Target(id,i),()->{var batch=batch(a,id);b.version(batch,i.expectedVersion());if(!"PREVIEW".equals(batch.get("status"))||ServiceDeskService.time(batch,"createdAt").isBefore(Instant.now().minusSeconds(86400)))throw ApiError.conflict("仅24小时内未入库批次可提交");List<Map<String,Object>> rows;try{rows=b.data.json.readValue(String.valueOf(batch.get("rowsData")),new com.fasterxml.jackson.core.type.TypeReference<List<Map<String,Object>>>(){});}catch(Exception e){throw new IllegalStateException(e);}if(rows.stream().anyMatch(x->!((List<?>)x.get("errors")).isEmpty()))throw ApiError.bad("请修正预校验错误后重新上传");long used=b.db.queryForObject("SELECT coalesce(sum(jsonb_array_length(results)),0)::bigint FROM crm_migration_batch WHERE tenant_id=:tenant AND status='COMMITTED' AND committed_at>=date_trunc('month',now() AT TIME ZONE 'Asia/Shanghai') AT TIME ZONE 'Asia/Shanghai'",map("tenant",a.tenant().id()),Long.class);if(used+rows.size()>((Number)p.plan(a).get("migration_monthly_row_limit")).longValue())throw ApiError.conflict("本月迁移行数已达到套餐上限");var ids=new ArrayList<Object>();int n=0;for(var row:rows){var values=(Map<String,String>)(Map<?,?>)row.get("values");Object made=create(a,(String)batch.get("entityType"),parse(a,(String)batch.get("entityType"),values),"mig:"+id+":"+(++n),trace);ids.add(r.object(made).get("id"));}b.db.update("UPDATE crm_migration_batch SET status='COMMITTED',results=cast(:results AS jsonb),version=version+1,committed_at=now() WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id,"results",b.json(ids)));b.audit(a,"MIGRATION_COMMITTED","MIGRATION",id,i.expectedVersion()+1,trace);return id;});return view(batch(a,result));});}
 public byte[] errors(AuthService.Session s,UUID id){return manage(s,false,a->{var data=view(batch(a,id));var rows=new ArrayList<List<Object>>();for(Object raw:(List<?>)data.get("rowsData")){var row=(Map<?,?>)raw;if(!((List<?>)row.get("errors")).isEmpty())rows.add(Arrays.asList(row.get("number"),String.join("；",((List<?>)row.get("errors")).stream().map(String::valueOf).toList())));}return CsvSupport.write(List.of("行号","错误说明"),rows);});}
}
